/**
 * Hand-rolled, committed service worker — not generated by a build step.
 *
 * next-pwa (Workbox) previously generated this file, but only under a webpack
 * build; Next 16 defaults to Turbopack, which never runs next-pwa's hook, so
 * this file silently stopped being produced. Production served a 404 for
 * /sw.js from 2026-08-05 until this file was committed as a real static asset
 * in public/ — see the investigation in project history for the evidence.
 * Pinning back to a webpack build would have revived next-pwa, but that ties
 * the whole app to a bundler Next is deprecating, for a plugin last published
 * in 2022, to regain precaching that had not actually been reachable in
 * production for three weeks anyway. This file is deliberately simple instead.
 *
 * Three responsibilities, all required by existing code that already assumes
 * them:
 *
 * 1. Background Sync replay for the offline outbox — see public/outbox-sync.js
 *    (COUPLED to lib/outbox.ts; see that file's header). Proxy.ts excludes
 *    both /sw.js and /outbox-sync.js from the auth matcher — an authenticated
 *    redirect in place of the script would throw here and fail SW install.
 *
 * 2. The "new version available" update banner — hooks/useServiceWorker.ts —
 *    posts exactly { type: 'SKIP_WAITING' } to a *waiting* worker from its
 *    applyUpdate() and expects this file to relay that into self.skipWaiting().
 *    Do NOT call self.skipWaiting() unconditionally on install: that would
 *    activate every new version immediately and silently defeat the banner,
 *    which exists so the user chooses when to switch versions.
 *
 *    That same hook reloads the page on ANY 'controllerchange' event, not
 *    just ones it caused — so self.clients.claim() must never run as a side
 *    effect of a plain first-time install. clients.claim() on every activate
 *    (a common copy-pasted pattern) makes a page that just loaded, with no
 *    prior controller, briefly "gain" one — which still fires
 *    'controllerchange' — so every first-time visitor would get an invisible,
 *    unwanted full-page reload a few hundred ms after landing. Verified live:
 *    an unguarded clients.claim() in 'activate' reliably produced a second
 *    `load` event on first visit in a fresh browser context. Claiming must
 *    happen only as a direct consequence of the explicit SKIP_WAITING
 *    message below, never from 'activate' on its own.
 *
 * 3. A narrowly-scoped home document fallback. Full, same-origin GET
 *    navigations to / are network-first and cache their successful response;
 *    only a network failure may reuse that exact URL. API calls, mutations,
 *    App Router RSC fetches, assets, and every non-home route pass through
 *    untouched. /offline.html is the only install-time precache and exists for
 *    the no-saved-home-yet case — this is deliberately not an app shell.
 */

importScripts('/outbox-sync.js');

const PAGE_CACHE_NAME = 'field-notes-pages-v1';
const OFFLINE_CACHE_NAME = 'field-notes-offline-v1';
const OFFLINE_URL = '/offline.html';
const RECONNECT_SCRIPT = `<script>
  (function () {
    let reloading = false;
    function reload() {
      if (reloading) return;
      reloading = true;
      window.location.reload();
    }
    window.addEventListener('online', reload, { once: true });
    const timer = window.setInterval(async function () {
      try {
        const response = await fetch('/manifest.json', { cache: 'no-store' });
        if (response.ok) {
          window.clearInterval(timer);
          reload();
        }
      } catch {}
    }, 5000);
  })();
</script>`;

async function withReconnectReload(response) {
  const html = await response.text();
  const headers = new Headers(response.headers);
  headers.delete('content-length');
  headers.delete('content-encoding');

  const body = html.includes('</head>')
    ? html.replace('</head>', `${RECONNECT_SCRIPT}</head>`)
    : `${RECONNECT_SCRIPT}${html}`;

  return new Response(body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

// Precache only the honest last-resort document. The authenticated home page
// remains network-first and is cached only after a successful navigation.
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(OFFLINE_CACHE_NAME).then((cache) => cache.add(OFFLINE_URL))
  );
});

// clients.claim() lives here, chained after skipWaiting() resolves, rather
// than in an 'activate' listener — see point 2 above for why 'activate' is
// the wrong place for it. This runs, and claims, only when the message below
// actually arrives.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    event.waitUntil(self.skipWaiting().then(() => self.clients.claim()));
  }
});

// registration.update() fetches /sw.js through the browser's service-worker
// update mechanism, outside this worker's own fetch handler. App Router soft
// navigations use RSC requests with mode "cors", so this deliberately handles
// only full document navigations to the home page.
self.addEventListener('fetch', (event) => {
  const request = event.request;
  const url = new URL(request.url);

  if (
    request.method !== 'GET' ||
    request.mode !== 'navigate' ||
    url.origin !== self.location.origin ||
    url.pathname !== '/'
  ) {
    return;
  }

  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request);
        const responseUrl = new URL(response.url);

        // Do not cache an auth redirect (or an error response) under the home
        // URL. Normal online navigations always receive the real response.
        if (
          response.ok &&
          !response.redirected &&
          responseUrl.origin === self.location.origin &&
          responseUrl.pathname === '/'
        ) {
          const cache = await caches.open(PAGE_CACHE_NAME);
          await cache.put(request, response.clone());
        }

        return response;
      } catch {
        const pageCache = await caches.open(PAGE_CACHE_NAME);
        const cachedPage = await pageCache.match(request);
        if (cachedPage) return withReconnectReload(cachedPage);

        const offlineCache = await caches.open(OFFLINE_CACHE_NAME);
        return offlineCache.match(OFFLINE_URL);
      }
    })()
  );
});
